        assertTrue(IdentityKinds.from(Map.of("companyCnpj", "1", "companyName", "A")).get() instanceof CnpjIdentity);
        assertTrue(IdentityKinds.from(Map.of("guestPassport", "1", "guestCountry", "A")).get() instanceof PassportIdentity);
    }
